prompt --application/shared_components/plugins/template_component/amc_next_timeline
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(527574412148127179)
,p_plugin_type=>'TEMPLATE COMPONENT'
,p_name=>'AMC_NEXT_TIMELINE'
,p_display_name=>'Next Timeline'
,p_supported_component_types=>'REPORT'
,p_partial_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<span class="amc-NTimeline-marker" aria-hidden="true">{if ?ICON/}<span class="amc-NTimeline-icon fa #ICON#"></span>{endif/}</span>',
'{if ?DATE/}<span class="amc-NTimeline-date">#DATE#</span>{endif/}',
'<div class="amc-NTimeline-card">',
'  <h3 class="amc-NTimeline-title">#TITLE#</h3>',
'  {if ?BODY/}<p class="amc-NTimeline-body">#BODY#</p>{endif/}',
'  <span class="amc-NTimeline-foot">{if ?TAG/}<span class="amc-NTimeline-tag">#TAG#</span>{endif/}<span class="amc-NTimeline-state">{case STATE/}{when success/}Done{when current/}In progress{when warning/}Attention{when danger/}Problem{when info/}Info{otherwise/}Pending{endcase/}</span></span>',
'</div>'))
,p_default_escape_mode=>'HTML'
,p_translate_this_template=>true
,p_api_version=>1
,p_report_body_template=>'<div class="amc-NTimeline amc-NTimeline--#STYLE#"><ol class="amc-NTimeline-list">#APEX$ROWS#</ol></div>'
,p_report_row_template=>'<li class="amc-NTimeline-item amc-NTimeline-item--{case STATE/}{when success/}success{when current/}current{when warning/}warning{when danger/}danger{when info/}info{otherwise/}neutral{endcase/}{if ?TAG/} amc-NTimeline-item--tagged{endif/}"{case STATE/}{when current/} aria-current="step"{endcase/}{case STYLE/}{when expandSteps/} tabindex="0"{endcase/}>#APEX$PARTIAL#</li>'
,p_css_file_urls=>'#PLUGIN_FILES#amc-next-timeline.css'
,p_substitute_attributes=>true
,p_subscribe_plugin_settings=>true
,p_help_text=>'Each query row is one event, in the order the query returns them. Pick a Style for the whole region, then map Title (required), Body, Date, Icon, State and Tag to columns. Format dates in SQL with the application''s NLS settings. State accepts success, current, warning, danger, info or neutral; any other value renders as neutral. For progress journeys return success for done steps, current for the active step and neutral for steps not reached yet. Pure CSS, no JavaScript.'
,p_version_identifier=>'1.0.1'
,p_files_version=>2
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(443841973636894327)
,p_plugin_id=>wwv_flow_imp.id(527574412148127179)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_static_id=>'STYLE'
,p_prompt=>'Style'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'beamRail'
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>'Design of the timeline; the direction is given in brackets as motion, depth, bold or smart. beamRail [motion]: a light pulse travels down the rail and a border beam circles the current event. pulseNow [motion]: done steps glow, the current step pulses, later steps wait on a dashed rail. perspectiveRoad [depth]: events line a road that recedes in perspective and flattens on hover or focus; order the query so the nearest event comes last. stackedCards3d [depth]: tilted cards cascade in depth and come forward on hover or focus. neoBrutal [bold]: ink rail, diamond markers, hard shadows and date stickers. clay [bold]: a clay groove with soft clay markers and cards. kineticYears [bold]: oversized outlined dates carry the structure and fill on hover or focus; return short dates such as 2026 or Q3. metroLine [bold]: a transit-map line with stations, horizontal in wide regions and vertical when narrow; a Tag turns a station into an interchange. scrollProgress [smart]: the rail fills and the markers light up as the list scrolls through the page; a static fill where scroll-driven animation is not supported. expandSteps [smart]: step panels that expand on hover, focus or tap to show the Body, side by side in wide regions and stacked when narrow; the current step is open at rest.'
);
